head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vJobMode = "";
scwin.vIsurCd = "";
scwin.vBzProcsNo = "";
scwin.vSeq = "";
scwin.vCMIT_CONTN_NM = "";
scwin.vCMIT_CONTN = "";
