///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.initCtrl();
        scwin.vJobMode = $c.frame.path("../").scwin.vJobMode;
        buttonSet.setSaveInfo(btn_save, scwin.save);
        buttonSet.setUpdateInfo(btn_update, scwin.update);
        buttonSet.setDeleteInfo(btn_delete, scwin.delete);
        if (scwin.vJobMode === "M") {
            btn_ISUR_CD.hide();
            btn_save.setDisabled(true);
            btn_save.setBackgroundImage("../img/btn_save_d.gif");
            scwin.vBzProcsNo = $c.frame.path("../").scwin.vBzProcsNo;
            scwin.vIsurCd = $c.frame.path("../").scwin.vIsurCd;
            vIsurNm = $c.frame.path("../").vIsurNm;
            txb_ISUR_CD.setValue(scwin.vIsurCd);
            txb_COM_NM.setValue(vIsurNm);
            buttonSet.setUpdateStatus();
            await scwin.listPreInvstg();
            await scwin.listSync();
        }
        if (scwin.vJobMode === "I") {
            await scwin.initDataset();
            buttonSet.setInsertStatus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41621.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

