/**
 * @method
 * @name grd_fileList_OnPopup
 * @description grd file List On Popup 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_OnPopup = function(row, colid, data) {
    try {
        if (colid === "filename") {
            scwin.cmitdeadlineFile();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41621.grd_fileList_OnPopup" });
    }
};

/**
 * @method
 * @name grd_fileList_OnDblClick
 * @description grd_fileList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_fileList_OnDblClick = async function(row, colid) {
    try {
        if (colid === "CMIT_CONTN_NM" || colid === "CMIT_CONTN") {
            await scwin.openCmitcontn(row);
        } else if (colid === "filename" && dts_fileList.getCellData(row, "filename") !== "") {
            scwin.cmitFiledown(row, "10");
        } else if (colid === "CMIT_PERFM_STAT_NM" || colid === "PERFM_OPIN_CONTN") {
            await scwin.openPerfm(row);
        } else if (colid === "CEVDN_filename" && dts_fileList.getCellData(row, "CEVDN_filename") !== "") {
            scwin.cmitFiledown(row, "20");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41621.grd_fileList_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_fileList_onlbuttondblclk
 * @description grd_fileList onlbuttondblclk 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} xpos xpos
 * @param {*} ypos ypos
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_onlbuttondblclk = function(row, colid, xpos, ypos) {
    try {
        if (colid === 'CMIT_DEADLINE_DD' && row > 0) {
            scwin.gridDateSet2(grd_fileList, row, colid, "yyyymmdd", xpos, ypos);
        }
        if (colid === 'CMIT_CONTN' && row > 0) {

        }
        return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41621.grd_fileList_onlbuttondblclk" });
    }
};

