/**
 * @method
 * @name initDataset
 * @description init Dataset 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initDataset = async function() {
    const sbmOptions = {
        id : "sbm_dts_ContentsInfo",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_ContentsInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_ContentsInfo.insertRow();
    const sbmOptions2 = {
        id : "sbm_dts_fileList",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_fileList=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

