/**
 * @method
 * @name approve
 * @description approve 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.approve = async function() {
    let cnt = 0;
    for (let i = 1; i <= dts_fileList.getRowCount(); i++) {
        if (dts_fileList.getCellData(i, "CHECK") === "T") cnt++;
    }
    if (cnt === 0) {
        await $c.win.alert("체크박스 선택한 항목이 없습니다.");
        return;
    } else {
        let rtn = confirm(cnt + "건 항목 승인 하시겠습니까?");
        if (rtn === 1) await scwin.approvelItems();
    }
};

