/**
 * @method
 * @name deleteItems
 * @description delete Items 처리
 * @returns {void}
 * @hidden N
 */
scwin.deleteItems = function() {
    grd_fileList.Redraw = false;
    dts_fileList.setBroadcast(false);
    for (let i = 1; i <= dts_fileList.getRowCount(); i++) {
        if (dts_fileList.getCellData(i, "CHECK") === "T") {
            dts_fileList.removeRow(i);
            i = i--;
        }
    }
    dts_fileList.setBroadcast(true, true);
    grd_fileList.Redraw = true;
};

